import { test, expect } from '@playwright/test';

test.describe('Confirm Password Mismatch Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/signup');
  });

  test('should display confirmation password mismatch error in real-time when passwords do not match', async ({ page }) => {
    // Setup: Fill in the first password field
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('Secure*Pass123');

    // Setup: Fill in the confirm password field
    const confirmPasswordInput = page.getByLabel('Confirm Password');
    await confirmPasswordInput.fill('Secure*Pass123');

    // Setup: Verify initial state of confirm password field
    const confirmPasswordField = page.getByLabel('Confirm Password');
    await expect(confirmPasswordField).toHaveValue('Secure*Pass123');

    // Setup: Verify error message is not visible initially
    const errorMessage = page.getByText('Passwords do not match');
    await expect(errorMessage).not.toBeVisible();

    // Setup: Fill in the confirm password field with a different value
    await confirmPasswordInput.fill('WrongPass123');

    // Setup: Verify error message appears
    await expect(errorMessage).toBeVisible();

    // Setup: Verify error message contains correct text
    await expect(errorMessage).toContainText('Passwords do not match');

    // Setup: Verify password field retains value
    await expect(passwordInput).toHaveValue('Secure*Pass123');

    // Setup: Verify confirm password field retains value
    await expect(confirmPasswordInput).toHaveValue('WrongPass123');

    // Setup: Verify error message is visible and styled
    await expect(errorMessage).toHaveClass(/error-message/);
  });

  test('should clear error message when passwords match after initial mismatch', async ({ page }) => {
    // Setup: Fill in the first password field
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('Secure*Pass123');

    // Setup: Fill in the confirm password field with a mismatch
    const confirmPasswordInput = page.getByLabel('Confirm Password');
    await confirmPasswordInput.fill('WrongPass123');

    // Setup: Verify error message appears
    const errorMessage = page.getByText('Passwords do not match');
    await expect(errorMessage).toBeVisible();

    // Setup: Verify error message contains correct text
    await expect(errorMessage).toContainText('Passwords do not match');

    // Setup: Verify password field retains value
    await expect(passwordInput).toHaveValue('Secure*Pass123');

    // Setup: Verify confirm password field retains value
    await expect(confirmPasswordInput).toHaveValue('WrongPass123');

    // Setup: Fill in the confirm password field with the correct value
    await confirmPasswordInput.fill('Secure*Pass123');

    // Setup: Verify error message is cleared
    await expect(errorMessage).not.toBeVisible();

    // Setup: Verify confirm password field retains the correct value
    await expect(confirmPasswordInput).toHaveValue('Secure*Pass123');

    // Setup: Verify password field retains value
    await expect(passwordInput).toHaveValue('Secure*Pass123');
  });
});
